from collections import Counter, deque

def transform_boxes(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); boxes=[]
    for r in range(h):
      for c in range(w):
        if (r,c) in seen or grid[r][c]==bg: continue
        col=grid[r][c]; q=deque([(r,c)]); seen.add((r,c)); comp=[]
        while q:
          y,x=q.popleft(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx));q.append((yy,xx))
        if len(comp)>=4:
          rs=[p[0] for p in comp];cs=[p[1] for p in comp]
          boxes.append((col,min(rs),max(rs),min(cs),max(cs)))
    out=[[bg]*w for _ in range(h)]
    # Preserve every large-component cell, then restore anomalous pixels inside that object's box.
    for col,r0,r1,c0,c1 in boxes:
      for r in range(r0,r1+1):
        for c in range(c0,c1+1): out[r][c]=col
    return out
